    #[inline]
    fn visit_return_stmt(&mut self, return_stmt: &mut ReturnStatement<'ast>) {
        self.walk_return_stmt(return_stmt);
    }

    #[inline]
    fn visit_compound_assignment(&mut self, compound_assignment: &mut CompoundAssignment<'ast>) {
        self.walk_compound_assignment(compound_assignment);
    }

    #[inline]
    fn visit_type_declaration(&mut self, type_declaration: &mut TypeDeclaration<'ast>) {
        self.walk_type_declaration(type_declaration);
    }

    #[inline]
    fn visit_type_declaration_value(
        &mut self,
        type_declaration_value: &mut TypeDeclarationValue<'ast>,
    ) {
        self.walk_type_declaration_value(type_declaration_value);
    }

    #[inline]
    fn visit_global_declaration(&mut self, global_declaration: &mut GlobalDeclaration<'ast>) {
        self.walk_global_declaration(global_declaration);
    }

    #[inline]
    fn visit_global_function(&mut self, global_function: &mut GlobalFunction<'ast>) {
        self.walk_global_function(global_function);
    }

    #[inline]
    fn visit_global_star(&mut self, global_star: &mut GlobalStar<'ast>) {
        self.walk_global_star(global_star);
    }

    #[inline]
    fn visit_type(&mut self, ty: &mut Type<'ast>) {
        self.walk_type(ty);
    }

    #[inline]
    fn visit_named_type(&mut self, named_type: &mut NamedType<'ast>) {
        self.walk_named_type(named_type);
    }

    #[inline]
    fn visit_type_args(&mut self, type_args: &mut TypeArgs<'ast>) {
        self.walk_type_args(type_args);
    }

    #[inline]
    fn visit_typeof_type(&mut self, typeof_type: &mut TypeofType<'ast>) {
        self.walk_typeof_type(typeof_type);
    }

    #[inline]
    fn visit_table_type(&mut self, table_type: &mut TableType<'ast>) {
        self.walk_table_type(table_type);
    }

